{"id": "v19/search-value/dir_desc", "version": 1, "symbol": "dir_desc", "kind": "value", "status": "Adapted", "category": "search-value", "definition": "Descending rank direction.", "aliases": ["highest first"], "shared_rules": ["v19/rule/category/search-value"]}
