{"id": "v19/support/illuminates", "version": 1, "symbol": "illuminates", "kind": "constructor", "status": "Accepted", "signature": "TERM illuminates(target: STRING / TERM, source: STRING / TERM) -> TERM", "definition": "Constructs a description of directional illumination where a light source casts light onto a target body.", "not": "an ambient color state or reflection (use reflects_light)", "aliases": ["illuminates", "shines on", "shining towards"], "shared_rules": ["v19/rule/support-primitives-general"]}

